#include "physics/OriginalVehiclePhysics.h"
#include <fstream>
#include <iostream>
#include <cstring>
#include <stdexcept>
namespace P=r3d::physics;
static float value(unsigned u){float v;std::memcpy(&v,&u,4);return v;}
static unsigned word(float v){unsigned u;std::memcpy(&u,&v,4);return u;}
static void vec(std::ostream&o,P::Vec3 v){o<<'['<<word(v.x)<<','<<word(v.y)<<','<<word(v.z)<<']';}
static void quat(std::ostream&o,P::Quat q){o<<'['<<word(q.x)<<','<<word(q.y)<<','<<word(q.z)<<','<<word(q.w)<<']';}
int main(int argc,char**argv){try{if(argc!=3)return 2;std::ifstream in(argv[1]);std::ofstream out(argv[2]);unsigned c,u;while(in>>c){P::Quat q;P::Vec3 omega;float damp[3];for(float*v:{&q.x,&q.y,&q.z,&q.w,&omega.x,&omega.y,&omega.z,&damp[0],&damp[1],&damp[2]}){in>>u;*v=value(u);}unsigned roll,pitch;in>>roll>>pitch;P::WorldDescription d;d.gravity=0;d.includeDeathPlane=false;d.startPosition={0,0,5};auto&v=d.vehicle;v.mass=1000;v.halfExtents={1,1,.25F};v.bodyLinearDamping=v.bodyAngularDamping=0;v.differentialRatio=3.42F;v.idlingRpm=1000;v.maximumRpm=7000;v.wheelContactsEnabled=false;v.maximumTorque=v.restBrakeTorque=v.brakeTorque=0;for(int i=0;i<4;++i){P::WheelDescription w;w.position={i<2?1.F:-1.F,i%2?1.F:-1.F,-.5F};w.radius=.5F;w.width=.2F;w.suspensionTravel=.4F;w.inverseMass=1;w.flags=0;w.longitudinalTire={1.F,.02F,2.F,.01F,0.F};w.lateralTire=w.longitudinalTire;w.driven=w.steering=i<2;v.wheels.push_back(w);}P::TriangleMesh floor;floor.vertices={{-500,-500,-1000},{500,-500,-1000},{500,500,-1000},{-500,500,-1000}};floor.indices={0,1,2,0,2,3};d.collisionMeshes.push_back(floor);std::string error;auto world=P::createOriginalVehicleWorld(d,error);if(!world)throw std::runtime_error(error);world->synchronizeNetworkVehicle(0,{0,0,5},q,{0,0,0},{0,0,0},true);world->addAngularVelocity(0,omega);auto before=world->vehicle();unsigned callbacks=0;world->setVehicleFixedStepController([&](std::size_t,float,const P::VehicleInput&,const P::VehicleFixedStepState& state){++callbacks;P::VehicleDriveCommand cmd;cmd.applyAngularStabilization=true;cmd.originalGameCarStabilization=true;cmd.angularDamping={{damp[0],damp[1],damp[2]}};cmd.clampRollAngle=value(roll);cmd.clampPitchAngle=value(pitch);return cmd;});world->step(1.F/60,P::VehicleInput{});auto after=world->vehicle();out<<"{\"case\":"<<c<<",\"callbacks\":"<<callbacks<<",\"rotation_before\":";quat(out,before.body.rotation);out<<",\"omega_before\":";vec(out,omega);out<<",\"cached_momentum_before\":";vec(out,before.angularMomentum);out<<",\"rotation_after_step\":";quat(out,after.body.rotation);out<<",\"momentum_after_step\":";vec(out,after.angularMomentum);out<<",\"position_after_step\":";vec(out,after.body.position);out<<"}\n";}return out.good()?0:4;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 3;}}
